def count_bidirectional(pairs):
    count = 0
    seen = set()

    for pair in pairs:
        forward = (pair[0], pair[1])
        reverse = (pair[1], pair[0])

        if forward in seen or reverse in seen:
            count += 1

        seen.add(pair)
        seen.add(reverse)

    return count
"""
  }
}
