def is_majority(arr, n, x):
    # Find the first occurrence of x using binary search
    i = find_first_occurrence(arr, x)

    # Check if the element at index i+n//2 is also x and i is not -1
    if i != -1 and i + n // 2 < n and arr[i + n // 2] == x:
        return True
    else:
        return False

def find_first_occurrence(arr, x):
    low = 0
    high = len(arr) - 1
    result = -1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == x:
            result = mid
            high = mid - 1  # Continue searching in the left half
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return result
"""
